void spawn_moby_offset_puffs(Moby_2FF358 *source_moby) __asm__("FUN_L14_002fded0");

void spawn_moby_offset_puffs(Moby_2FF358 *source_moby) {
    Vec_2FF358 A;
    Vec_2FF358 B;
    Vec_2FF358 C;
    Part      *puff;
    int        i, j, puff_signed_amount, puff_lifetime_frames, k, col;
    float      puff_size;

    fast_vec_scale(A, source_moby->right, bolt_thief_puff_initial_right_offset_gp);
    fast_vec_add(B, source_moby->pos, A);
    fast_vec_scale(A, source_moby->up, bolt_thief_puff_up_offset_gp);
    fast_vec_add(B, B, A);
    qcopy(C, B);
    fast_vec_scale(A, source_moby->fwd, bolt_thief_puff_forward_offset_gp);
    fast_vec_add(B, B, A);
    for (i = 1; i >= 0; i--) {
        puff_signed_amount = random_integer_below(0x10);
        k = random_integer_below(2) == 0 ? puff_signed_amount : -puff_signed_amount;
        puff = spawn_puff(B, 0.2f, 1.0f, 0.9f, k, &D_L14_0015F580, 200000.0f, D_L14_00161FA4);
        if (puff != 0) {
            struct PartSub *f = &puff->sub;

            puff->life = scale_game_frames(0xC);
            f->f4 = 2;
            f->bA = 0x7F;
            f->bB = puff->life;
        }
    }
    fast_vec_scale(A, source_moby->right, bolt_thief_puff_middle_right_offset_delta_gp);
    puff_size = 100000.0f;
    fast_vec_add(B, B, A);
    puff_signed_amount = 0x10;
    puff_lifetime_frames = scale_game_frames(2);
    for (j = 0; j < 3; j++) {
        puff = spawn_puff(
            B, 0.05f, 1.0f, 1.0f, puff_signed_amount, &D_L14_0015F580, puff_size, 0x7FFFFFFF);
        if (puff != 0) {
            struct PartSub *f = &puff->sub;

            puff->life = puff_lifetime_frames;
            puff->b8 = random_integer_below(0xFF);
            f->f4 = 2;
            f->bA = 0x7F;
            f->bB = puff->life;
        }
        puff_signed_amount = -puff_signed_amount;
        puff_lifetime_frames = puff_lifetime_frames << 1;
        puff_size = puff_size - 20000.0f;
    }
    puff_size = 300000.0f;
    fast_vec_scale(A, source_moby->right, bolt_thief_puff_final_right_offset_gp);
    fast_vec_add(B, C, A);
    col = random_int_between(0x40, 0x80);
    k = (col << 8) | 0x7F000000;
    col = col | ((col << 16) | k);
    if (random_integer_below(3)) {
        Part *final_puff;

        puff_signed_amount = random_integer_below(4);
        k = random_integer_below(2) == 0 ? puff_signed_amount : -puff_signed_amount;
        final_puff = spawn_puff(B, 0.05f, 1.0f, 1.0f, k, &D_L14_0015F580, puff_size, col);
        if (final_puff != 0) {
            struct PartSub *f = &final_puff->sub;

            final_puff->life = scale_game_frames(0x3C);
            if (random_integer_below(2)) {
                final_puff->b3 = 0x44;
            }
            f->bA = 0x40;
            f->f4 = 2;
            f->bB = scale_game_frames(0x3C);
        }
    }
}

